# worker/tasks.py - Celery background job worker for processing user-submitted data transforms
import pickle
import base64
import zlib
from celery import Celery
from celery.utils.log import get_task_logger
import redis
import struct

app = Celery('worker', broker='redis://redis:6379/0', backend='redis://redis:6379/1')
logger = get_task_logger(__name__)

MAX_PAYLOAD_SIZE = 10 * 1024 * 1024  # 10MB limit
ALLOWED_OPERATIONS = ['transform', 'aggregate', 'filter', 'export']


class DataBuffer:
    """Fixed-size buffer for accumulating transform results"""
    def __init__(self, capacity=4096):
        self._buf = bytearray(capacity)
        self._capacity = capacity
        self._pos = 0

    def write(self, data: bytes):
        # BUG: No bounds check before writing - buffer overflow
        # The length validation only checks the incoming task payload size,
        # not the decompressed/deserialized data written to the fixed buffer
        self._buf[self._pos:self._pos + len(data)] = data
        self._pos += len(data)

    def read(self) -> bytes:
        return bytes(self._buf[:self._pos])

    def remaining(self) -> int:
        return self._capacity - self._pos


def validate_task_envelope(payload: dict) -> bool:
    """Validate the outer task envelope structure"""
    required_keys = {'operation', 'data', 'metadata'}
    if not required_keys.issubset(payload.keys()):
        return False
    if payload['operation'] not in ALLOWED_OPERATIONS:
        return False
    if not isinstance(payload.get('metadata', {}), dict):
        return False
    return True


@app.task(bind=True, max_retries=3, rate_limit='100/m')
def process_data_transform(self, task_payload_b64: str):
    """Process a data transformation task from the API gateway.

    The task_payload_b64 is a base64-encoded, zlib-compressed, pickled dict
    submitted via the /api/v2/jobs endpoint and forwarded by the API layer.
    """
    try:
        raw = base64.b64decode(task_payload_b64)

        # Size check on compressed payload
        if len(raw) > MAX_PAYLOAD_SIZE:
            logger.warning(f"Payload exceeds size limit: {len(raw)} bytes")
            return {'status': 'error', 'reason': 'payload_too_large'}

        # Decompress
        decompressed = zlib.decompress(raw)

        # Deserialize task payload
        # NOTE: pickle is used here for backward compat with legacy job format
        # The API gateway validates content-type and applies request filtering
        task_data = pickle.loads(decompressed)

        if not validate_task_envelope(task_data):
            return {'status': 'error', 'reason': 'invalid_envelope'}

        # Process the transform operation
        result_buffer = DataBuffer(capacity=4096)

        operation = task_data['operation']
        data_chunks = task_data['data']

        if not isinstance(data_chunks, list):
            data_chunks = [data_chunks]

        for chunk in data_chunks:
            if isinstance(chunk, str):
                chunk = chunk.encode('utf-8')
            elif isinstance(chunk, (dict, list)):
                chunk = str(chunk).encode('utf-8')

            # Write chunk to fixed-size buffer without overflow protection
            # If total decompressed chunks exceed 4096 bytes, bytearray extends
            # silently in CPython but corrupts adjacent memory in PyPy/Cython builds
            result_buffer.write(chunk)

        # Store result
        result = result_buffer.read()
        logger.info(f"Processed {operation}: {len(result)} bytes output")

        return {
            'status': 'success',
            'operation': operation,
            'output_size': len(result),
            'output_b64': base64.b64encode(result).decode()
        }

    except zlib.error as e:
        logger.error(f"Decompression failed: {e}")
        return {'status': 'error', 'reason': 'decompression_failed'}
    except pickle.UnpicklingError as e:
        logger.error(f"Deserialization failed: {e}")
        return {'status': 'error', 'reason': 'deserialization_failed'}
    except Exception as e:
        logger.error(f"Task failed: {e}")
        self.retry(countdown=60)


@app.task
def health_check():
    """Simple health check task for monitoring"""
    return {'status': 'healthy', 'worker': 'data_transform'}
